fn is_close_i8(a: i8, b: i8, tol: i8) -> bool {
    // Calculate the difference
    let diff = a.wrapping_sub(b);
    
    // Check if the absolute difference is strictly less than tolerance
    // Since tolerance is strictly positive, we can use this approach
    diff.abs() < tol
}

fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> Vec<bool> {
    // The problem states that arrays have equal, non-zero length
    // and tolerance is strictly positive, so we don't need to check those
    
    // Create result vector with the same length as input arrays
    let mut result = Vec::with_capacity(a.len());
    
    // Iterate through both arrays simultaneously
    for (a_val, b_val) in a.iter().zip(b.iter()) {
        // Calculate difference and check if within tolerance
        let diff = a_val.wrapping_sub(*b_val);
        result.push(diff.abs() < tol);
    }
    
    result
}